CREATE TABLE deployment(singleton INTEGER PRIMARY KEY CHECK(singleton=1), organization_id TEXT NOT NULL UNIQUE);
CREATE TABLE principals(id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('user','agent')));
CREATE TABLE tasks(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES deployment(organization_id),created_by TEXT NOT NULL REFERENCES principals(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT,title TEXT NOT NULL,notes TEXT,status TEXT NOT NULL CHECK(status IN ('open','done')),due_at TEXT,completed_at TEXT,assignee_id TEXT REFERENCES principals(id),UNIQUE(organization_id,id));
CREATE TABLE companies(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES deployment(organization_id),created_by TEXT NOT NULL REFERENCES principals(id),name TEXT NOT NULL,UNIQUE(organization_id,id));
CREATE TABLE contacts(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES deployment(organization_id),created_by TEXT NOT NULL REFERENCES principals(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT,name TEXT,company_id TEXT,merged_into_id TEXT,UNIQUE(organization_id,id),CHECK(merged_into_id IS NULL OR deleted_at IS NOT NULL),CHECK(merged_into_id<>id),FOREIGN KEY(organization_id,company_id) REFERENCES companies(organization_id,id),FOREIGN KEY(organization_id,merged_into_id) REFERENCES contacts(organization_id,id));
CREATE TABLE identities(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES deployment(organization_id),created_by TEXT NOT NULL REFERENCES principals(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT,kind TEXT NOT NULL CHECK(kind IN ('email','phone')),value TEXT NOT NULL,contact_id TEXT,own INTEGER NOT NULL CHECK(own IN (0,1)),CHECK(own=(contact_id IS NULL)),FOREIGN KEY(organization_id,contact_id) REFERENCES contacts(organization_id,id),UNIQUE(organization_id,id));
CREATE UNIQUE INDEX identities_live_address ON identities(organization_id,kind,value) WHERE deleted_at IS NULL;
CREATE TABLE events(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES deployment(organization_id),actor_id TEXT NOT NULL REFERENCES principals(id),created_at TEXT NOT NULL,type TEXT NOT NULL,resource_type TEXT NOT NULL,resource_id TEXT NOT NULL,before TEXT CHECK(before IS NULL OR json_valid(before)),after TEXT CHECK(after IS NULL OR json_valid(after)));
CREATE TABLE prototype_operations(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES deployment(organization_id),actor_id TEXT NOT NULL REFERENCES principals(id),created_at TEXT NOT NULL,input TEXT NOT NULL CHECK(json_valid(input)),outcome TEXT CHECK(outcome IS NULL OR json_valid(outcome)),UNIQUE(organization_id,id));
CREATE TABLE prototype_rows(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES deployment(organization_id),actor_id TEXT NOT NULL REFERENCES principals(id),created_at TEXT NOT NULL,operation_id TEXT NOT NULL,slot TEXT NOT NULL,ordinal INTEGER NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),FOREIGN KEY(organization_id,operation_id) REFERENCES prototype_operations(organization_id,id),UNIQUE(organization_id,operation_id,slot,ordinal));
